fn first(v: &Vec[Int]) -> Option[Int] {
  if v.len() == 0 { return None; }
  return Some(v[0]);
}

fn longer(a: &Vec[Int], b: &Vec[Int]) -> &Vec[Int] {
  if a.len() >= b.len() { return a; }
  return b;
}

fn main() -> Int {
  let v1 = Vec[Int]();
  v1.push(10); v1.push(20);
  let v2 = Vec[Int]();
  v2.push(100);
  let chosen = longer(&v1, &v2);
  var sum = 0;
  var i = 0;
  while i < chosen.len() {
    sum = sum + chosen[i];
    i = i + 1;
  }
  return sum;
}
